SELECT
ordered.*,
user.name as userName,
film.title as filmName,
cinema.name as cinemaName,
IFNULL(room.name, '暂未关联影厅') as roomName
FROM ordered
LEFT JOIN user ON ordered.user_id = user.id
LEFT JOIN film ON ordered.film_id = film.id
LEFT JOIN cinema ON ordered.cinema_id = cinema.id
LEFT JOIN room ON ordered.room_id = room.id

    AND ordered.orders LIKE CONCAT('%', #{orders}, '%')
    AND ordered.status = #{status}
    AND ordered.record_id = #{recordId} 
    AND ordered.user_id = #{userId} 
    AND ordered.film_id = #{filmId} 
    AND ordered.cinema_id = #{cinemaId} 
    AND ordered.room_id = #{roomId} 

ORDER BY id DESC

SELECT COUNT(*) FROM ordered
WHERE user_id = #{userId}
  AND film_id = #{filmId}
  AND status = '已取票'

